  'app-pulse-club': { brand:'AFIA CLUB', icon:'◉', accent:'#2a8879', screens:['dashboard','classes','membership'], classes:[['strength','قوة أساسية','Core strength','اليوم · 18:00','Today · 18:00','سارة منصور','Sara Mansour',8],['mobility','حركة ومرونة','Mobility flow','غداً · 09:00','Tomorrow · 09:00','ليث عودة','Laith Odeh',12],['cardio','دائرة لياقة','Fitness circuit','الخميس · 19:30','Thursday · 19:30','ريم خليل','Reem Khalil',5]] },
