  'app-campus-records': { brand:'MADRASATI', icon:'⌂', accent:'#476bb2', screens:['overview','students','attendance'], students:[['ST-1042','ليان أحمد','Layan Ahmad','الصف الثامن','Grade 8','منتظمة','Active'],['ST-1077','عمر سامر','Omar Samer','الصف التاسع','Grade 9','متابعة','Follow-up'],['ST-1103','سلمى ناصر','Salma Nasser','الصف الثامن','Grade 8','منتظمة','Active'],['ST-1130','آدم ياسين','Adam Yasin','الصف السابع','Grade 7','منتظم','Active']] },
