function inventory(h,item,s){
 const c=catalog[item.id], products=c.products, sales=s.sales||[];
 const qty=(p)=>Math.max(0,p[4]+(Number(s.stockAdjustments[p[0]])||0));
 if(s.screen==='inventory')return `<header class="za-page-head"><div><small>STOCK CONTROL / 02</small><h2>${h.tx('الأصناف وحركتها.','Stock and movement.')}</h2><p>${h.tx('عدّل الكميات وشاهد أثر الحركة فوراً داخل المعاينة.','Adjust quantities and see the local demo update immediately.')}</p></div><label class="za-search">⌕ <input data-search type="search" value="${esc(h,s.query)}" placeholder="${h.tx('ابحث باسم الصنف','Search items')}"></label></header><div class="za-inventory-table"><div class="za-table-head"><span>${h.tx('الصنف','Item')}</span><span>${h.tx('المخزن','Location')}</span><span>${h.tx('الكمية المتاحة','On hand')}</span><span>${h.tx('إجراء','Action')}</span></div>${products.filter(p=>!s.query||p[1].includes(s.query)||p[2].toLowerCase().includes(s.query.toLowerCase())).map(p=>`<article><span class="za-stock-name"><i>${p[0]==='oil'?'◉':p[0]==='coffee'?'◍':'◈'}</i><b>${h.tx(p[1],p[2])}<small>SKU-${p[0].toUpperCase()}-0${products.indexOf(p)+1}</small></b></span><span>${h.tx(p[5],p[6])}</span><strong class="${qty(p)<10?'low':''}">${qty(p)} ${h.tx('قطعة','units')}</strong><span class="za-stock-actions"><button type="button" data-stock="${p[0]}" data-delta="-1">−</button><button type="button" data-stock="${p[0]}" data-delta="1">＋</button></span></article>`).join('')}</div>`;
 if(s.screen==='sales')return `<header class="za-page-head"><div><small>SALES / 03</small><h2>${h.tx('مبيعات المعاينة','Demo sales')}</h2><p>${h.tx('سجّل حركة بيع افتراضية لتحديث الملخص المحلي.','Add a sample sale to update this local overview.')}</p></div><button type="button" class="za-primary" data-action="sale">＋ ${h.tx('تسجيل بيع تجريبي','Record demo sale')}</button></header><div class="za-sales-table">${sales.length?sales.map(x=>`<article><span>↗</span><div><b>${esc(h,x.product)}</b><small>${esc(h,x.id)} · ${new Date(x.at).toLocaleString(h.lang()==='en'?'en':'ar')}</small></div><strong>${money(h,x.total)}</strong></article>`).join(''):`<div class="za-empty">↗<b>${h.tx('لا توجد مبيعات تجريبية بعد','No demo sales yet')}</b><span>${h.tx('استخدم تسجيل بيع لإضافة أول حركة محلية.','Use Record sale to add the first local entry.')}</span></div>`}</div><aside class="za-demo-hint">${h.tx('كل عملية بيع تجريبية تخص هذا التبويب فقط.','All sample sales belong to this browser tab only.')}</aside>`;
 const low=products.filter(p=>qty(p)<10).length, value=products.reduce((n,p)=>n+Number(p[3])*qty(p),0);
 return `<header class="za-page-head"><div><small>MAKHZANI / OPERATIONS</small><h2>${h.tx('صباح الخير، فريق المتجر.','Good morning, store team.')}</h2><p>${h.tx('إليك نظرة سريعة على المخزون والمبيعات.','A quick view of inventory and sales activity.')}</p></div><button class="za-primary" type="button" data-screen="inventory">${h.tx('إدارة المخزون','Manage stock')} ↗</button></header><div class="za-kpi-grid">${kpi(h,h.tx('أصناف نشطة','Active products'),products.length,h.tx('في هذه التجربة','In this demo'),'▤')}${kpi(h,h.tx('قيمة المخزون','Stock value'),money(h,value),h.tx('قيمة توضيحية','Sample value'),'◉')}${kpi(h,h.tx('مخزون منخفض','Low stock'),low,h.tx('تحتاج مراجعة','Needs review'),'!')}${kpi(h,h.tx('مبيعات تجريبية','Demo sales'),sales.length,h.tx('محفوظة محلياً','Saved locally'),'↗')}</div><div class="za-inventory-overview"><section class="za-panel"><header><div><small>LOW STOCK</small><h3>${h.tx('أصناف تحتاج انتباهاً','Needs attention')}</h3></div><button type="button" data-screen="inventory">${h.tx('كل الأصناف','All items')} ↗</button></header>${products.filter(p=>qty(p)<20).map(p=>`<article class="za-low-row"><i class="${qty(p)<10?'critical':''}">!</i><b>${h.tx(p[1],p[2])}<small>${esc(h,p[5])}</small></b><strong>${qty(p)}</strong></article>`).join('')||`<div class="za-empty">✓ ${h.tx('المخزون يبدو جيداً.','Stock looks healthy.')}</div>`}</section><section class="za-panel"><header><div><small>QUICK ACTION</small><h3>${h.tx('تسجيل بيع','Record a sale')}</h3></div><span>＋</span></header><p>${h.tx('اختر منتجاً من القائمة لتسجيل عملية بيع توضيحية وتحديث الكمية.','Choose an item to record a sample sale and update stock.')}</p><label class="za-select-label">${h.tx('الصنف','Product')}<select data-field="saleProduct">${products.map(p=>`<option value="${p[0]}">${h.tx(p[1],p[2])} · ${money(h,p[3])}</option>`).join('')}</select></label><button class="za-primary full" type="button" data-action="sale">${h.tx('تسجيل بيع تجريبي','Record sample sale')} ↗</button></section></div>`;
}

function campus(h,item,s){
 const c=catalog[item.id], rows=c.students.filter(x=>(!s.query||x[1].includes(s.query)||x[2].toLowerCase().includes(s.query.toLowerCase()))&&(s.filter==='all'||x[5]===s.filter));
 if(s.screen==='students')return `<header class="za-page-head"><div><small>STUDENT DIRECTORY / 02</small><h2>${h.tx('ملفات الطلاب','Student records')}</h2><p>${h.tx('سجل مدرسي افتراضي لتجربة البحث والمراجعة.','Sample school register for search and review.')}</p></div><label class="za-search">⌕ <input data-search type="search" value="${esc(h,s.query)}" placeholder="${h.tx('ابحث بالاسم أو الرقم','Search name or ID')}"></label></header><div class="za-filter-row"><button class="${s.filter==='all'?'active':''}" type="button" data-filter="all">${h.tx('الكل','All')}</button><button class="${s.filter==='Active'?'active':''}" type="button" data-filter="Active">${h.tx('منتظم','Active')}</button><button class="${s.filter==='Follow-up'?'active':''}" type="button" data-filter="Follow-up">${h.tx('متابعة','Follow-up')}</button><span>${rows.length} ${h.tx('طلاب','students')}</span></div><div class="za-student-list">${rows.map(x=>`<button type="button" data-student="${x[0]}" class="za-student-row"><span class="za-student-avatar">${x[1].slice(0,1)}</span><b>${h.tx(x[1],x[2])}<small>${x[0]} · ${h.tx(x[3],x[4])}</small></b><span class="za-status ${x[5]==='Follow-up'?'attention':''}">${h.tx(x[5],x[6])}</span><span>›</span></button>`).join('')||`<div class="za-empty">⌕<b>${h.tx('لم نعثر على طالب مطابق','No matching student')}</b><span>${h.tx('غيّر عبارة البحث وحاول مجدداً.','Change the search and try again.')}</span></div>`}</div>`;
 if(s.screen==='attendance')return `<header class="za-page-head"><div><small>ATTENDANCE / 03</small><h2>${h.tx('الحضور اليومي','Daily attendance')}</h2><p>${h.tx('حالة افتراضية؛ علّم حضور الطلاب لاستكشاف الواجهة.','Sample roster. Mark attendance to explore the interface.')}</p></div><span class="za-step-pill">${h.tx('الأربعاء · ٤ نوفمبر','WED · NOV 4')}</span></header><div class="za-attendance-list">${c.students.map(x=>`<article><span class="za-student-avatar">${x[1].slice(0,1)}</span><b>${h.tx(x[1],x[2])}<small>${x[0]} · ${h.tx(x[3],x[4])}</small></b><button type="button" class="${s.attendance[x[0]]?'present':''}" data-attendance="${x[0]}">${s.attendance[x[0]]?'✓ '+h.tx('حاضر','Present'):h.tx('تسجيل الحضور','Mark present')}</button></article>`).join('')}</div><div class="za-demo-hint">${Object.values(s.attendance).filter(Boolean).length} / ${c.students.length} ${h.tx('حضور مسجّل في التجربة','attendance marks in demo')}</div>`;
 if(s.screen==='student-detail'){const student=c.students.find(x=>x[0]===s.selected)||c.students[0];return `<header class="za-page-head"><button class="za-outline" type="button" data-screen="students">← ${h.tx('عودة للسجل','Back to records')}</button><small>STUDENT PROFILE / ${student[0]}</small></header><div class="za-student-profile"><span class="za-student-avatar big">${student[1].slice(0,1)}</span><div><span class="za-status ${student[5]==='Follow-up'?'attention':''}">${h.tx(student[5],student[6])}</span><h2>${h.tx(student[1],student[2])}</h2><p>${student[0]} · ${h.tx(student[3],student[4])}</p></div></div><div class="za-kpi-grid">${kpi(h,h.tx('متوسط التقييم','Average score'),'88%',h.tx('هذا الفصل · توضيحي','This term · sample'),'◒')}${kpi(h,h.tx('الحضور','Attendance'),'94%',h.tx('آخر ٣٠ يوماً','Last 30 days'),'✓')}${kpi(h,h.tx('واجبات قيد التسليم','Assignments due'),'2',h.tx('تذكير توضيحي','Sample reminder'),'▤')}</div><section class="za-panel"><header><div><small>RECENT NOTES</small><h3>${h.tx('ملاحظات أكاديمية','Academic notes')}</h3></div></header><p>${h.tx('يشارك بفاعلية في الصف، ويستفيد من المراجعة القصيرة قبل الاختبارات.','Participates well in class and benefits from a short review before quizzes.')}</p></section>`;}
 return `<header class="za-page-head"><div><small>MADRASATI / SCHOOL SPACE</small><h2>${h.tx('مرحباً، أ. سارة.','Welcome, Ms. Sara.')}</h2><p>${h.tx('إدارة أكاديمية منظمة تبدأ بصورة واضحة عن اليوم.','A well-organized school day starts with a clear overview.')}</p></div><button class="za-primary" type="button" data-screen="students">${h.tx('استكشف سجل الطلاب','Open student records')} ↗</button></header><div class="za-campus-banner">${photo(h,item,'MADRASATI · SCHOOL PORTAL')}<div><small>GRADE 8 / TERM 1</small><h3>${h.tx('متابعة الطالب، بتفاصيل تساعده.','Student progress, with the detail that helps.')}</h3><p>${h.tx('لوحة مدرس تجريبية للحضور والتقدم والملاحظات.','A sample teacher view for attendance, progress, and notes.')}</p></div></div><div class="za-kpi-grid">${kpi(h,h.tx('الطلاب المسجلون','Enrolled students'),c.students.length,h.tx('في هذه العينة','In this sample'),'♙')}${kpi(h,h.tx('حضور اليوم','Present today'),`${Object.values(s.attendance).filter(Boolean).length} / ${c.students.length}`,h.tx('سجل توضيحي','Sample roster'),'✓')}${kpi(h,h.tx('متوسط الصف','Class average'),'88%',h.tx('بيانات افتراضية','Sample data'),'◒')}</div><div class="za-campus-shortcuts"><button type="button" data-screen="students"><i>♙</i><b>${h.tx('ملفات الطلاب','Student records')}<small>${h.tx('بحث ومراجعة البيانات المدرسية','Search and review school records')}</small></b><span>↗</span></button><button type="button" data-screen="attendance"><i>✓</i><b>${h.tx('الحضور اليومي','Daily attendance')}<small>${h.tx('سجل حضور تجريبي','Demo attendance register')}</small></b><span>↗</span></button></div>`;
}

function serveflow(h,item,s){
 const c=catalog[item.id], requests=s.requests||[];
 if(s.screen==='requests')return `<header class="za-page-head"><div><small>MY SERVICE REQUESTS / 02</small><h2>${h.tx('متابعة طلباتك','Your service requests')}</h2><p>${h.tx('طلبات الخدمة داخل هذه المعاينة محلية فقط.','Service requests in this preview stay local.')}</p></div><button class="za-primary" type="button" data-screen="services">＋ ${h.tx('اطلب خدمة','Request a service')}</button></header><div class="za-request-list">${requests.length?requests.map(x=>`<article><span class="za-request-icon">⌁</span><div><small>${esc(h,x.id)} · ${h.tx('طلب تجريبي','DEMO REQUEST')}</small><b>${h.tx(x.serviceAr,x.serviceEn)}</b><span>${esc(h,x.date)} · ${esc(h,x.time)}</span></div><strong class="za-status">${h.tx('تم الاستلام · تجريبي','Received · demo')}</strong></article>`).join(''):`<div class="za-empty">⌁<b>${h.tx('لا توجد طلبات خدمة بعد','No service requests yet')}</b><span>${h.tx('اختر خدمة ووقتاً لمعاينة الخطوات.','Choose a service and time to preview the flow.')}</span></div>`}</div>`;
 if(s.screen==='service-detail'){const service=c.services.find(x=>x[0]===s.selected)||c.services[0];return `<header class="za-page-head"><button class="za-outline" type="button" data-screen="services">← ${h.tx('عودة للخدمات','Back to services')}</button><small>HARFI SERVICE / ${service[0].toUpperCase()}</small></header><article class="za-service-detail"><div class="za-service-illustration">${photo(h,item,'HARFI · LOCAL SERVICE')}</div><div><span class="za-eyebrow">${h.tx('خدمة منزلية','HOME SERVICE')}</span><h2>${h.tx(service[1],service[2])}</h2><p>${h.tx(service[3],service[4])}</p><ul><li>${h.tx('فني موثّق · مثال توضيحي','Sample provider profile')}</li><li>${h.tx('اختيار وقت حسب التوفر','Choose a sample time')}</li><li>${h.tx('السعر تقديري للعرض','Illustrative sample price')}</li></ul><strong>${money(h,service[5])} <small>${h.tx('ابتداءً · توضيحي','from · sample')}</small></strong><button class="za-primary" type="button" data-action="continue-booking">${h.tx('اختر موعداً','Choose a time')} ↗</button></div></article>`;}
 if(s.screen==='booking') {const service=c.services.find(x=>x[0]===s.selected)||c.services[0];return `<header class="za-page-head"><div><small>REQUEST / 02</small><h2>${h.tx('متى يناسبك؟','When works for you?')}</h2><p>${h.tx(h.tx(service[1],service[2]),h.tx(service[1],service[2]))} · ${h.tx('معاينة محلية','LOCAL PREVIEW')}</p></div><button class="za-outline" type="button" data-screen="service-detail">← ${h.tx('رجوع','Back')}</button></header><div class="za-booking-panel"><label>${h.tx('اليوم المناسب','Preferred day')}<select data-field="date"><option>${h.tx('الخميس ٥ نوفمبر','Thursday, Nov 5')}</option><option>${h.tx('الجمعة ٦ نوفمبر','Friday, Nov 6')}</option><option>${h.tx('الأحد ٨ نوفمبر','Sunday, Nov 8')}</option></select></label><div><b>${h.tx('الأوقات المتاحة','Sample time slots')}</b><div class="za-times">${['10:00','12:30','15:00','17:30'].map(x=>`<button type="button" data-time="${x}" class="${s.selectedTime===x?'selected':''}">${x}</button>`).join('')}</div></div><p class="za-demo-hint">ⓘ ${h.tx('لا تدخل رقماً أو اسماً حقيقياً. الحجز تجريبي ولن يصل إلى مزود خدمة.','Do not enter real contact details. This booking is a demo and will not reach a provider.')}</p><button type="button" class="za-primary" data-action="confirm-service" ${s.selectedTime?'':'disabled'}>${h.tx('تأكيد طلب تجريبي','Confirm demo request')} ↗</button></div>`;}
 const service=c.services.find(x=>x[0]===s.selected)||c.services[0];
 return `<header class="za-page-head"><div><small>HARFI / SERVICE NETWORK</small><h2>${h.tx('مساعدة موثوقة، بخطوات أسهل.','Trusted help, with simpler steps.')}</h2><p>${h.tx('اختر نوع الخدمة واستكشف تفاصيل المعاينة.','Select a service and explore the sample flow.')}</p></div><button class="za-outline" type="button" data-screen="requests">${h.tx('طلباتي','My requests')} <b class="za-badge">${requests.length}</b></button></header><div class="za-serve-hero">${photo(h,item,'HARFI · HOME SERVICES')}<div><span class="za-eyebrow">${h.tx('خدمات منزلية في مكان واحد','HOME HELP, MADE SIMPLE')}</span><h3>${h.tx('اختر الخدمة. حدّد وقتك.','Choose a service. Pick your time.')}</h3><p>${h.tx('تجربة توضيحية لا تتصل بفنيين أو مزودي خدمات حقيقيين.','A demo flow that does not connect to real service providers.')}</p></div></div><section class="za-section"><div class="za-section-head"><div><small>AVAILABLE SERVICES</small><h3>${h.tx('بماذا تحتاج المساعدة؟','What can we help with?')}</h3></div><span>${c.services.length} ${h.tx('خدمات','SERVICES')}</span></div><div class="za-service-grid">${c.services.map(x=>`<article class="za-harfi-card"><i>${x[0]==='electric'?'ϟ':x[0]==='plumbing'?'◌':x[0]==='cooling'?'❄':'⌂'}</i><small>HARFI / ${x[0].toUpperCase()}</small><h3>${h.tx(x[1],x[2])}</h3><p>${h.tx(x[3],x[4])}</p><footer><b>${money(h,x[5])} <small>${h.tx('تقريباً','approx.')}</small></b><button type="button" data-service="${x[0]}">${h.tx('التفاصيل','Details')} ↗</button></footer></article>`).join('')}</div></section>`;
}

const renderers={'app-slotbook':slotbook,'app-palm-cart':storeScreen,'app-saffron-run':storeScreen,'app-pocket-ledger':ledger,'app-spark-study':study,'app-pulse-club':fitness,'app-shelfwise':inventory,'app-campus-records':campus,'app-serveflow':serveflow};
export function renderAppsDemo(item,helpers){const c=catalog[item.id];if(!c)return '';const state=load(item.id);return shell(helpers,item,state,renderers[item.id](helpers,item,state,item.id==='app-saffron-run'));}

export function mountAppsDemo(root,item,helpers){
 const c=catalog[item.id];if(!c)return;
 const draw=()=>{root.innerHTML=renderAppsDemo(item,helpers)};
 const mutate=fn=>{const state=load(item.id);fn(state);save(item.id,state);draw()};
 root.addEventListener('click',event=>{
   const host=event.target.closest('[data-zfx-app]');if(!host||host.dataset.zfxApp!==item.id)return;
   const target=event.target.closest('button');if(!target)return;
   if(target.matches('[data-action="reset"]')){sessionStorage.removeItem(STORE_KEY(item.id));draw();helpers.notice(helpers.tx('تمت إعادة ضبط هذه التجربة.','This demo has been reset.'));return}
   if(target.dataset.screen){mutate(s=>{s.screen=target.dataset.screen;s.notice='';if(s.screen==='lesson')s.quiz=''});return}
   if(target.dataset.service){mutate(s=>{s.selected=target.dataset.service;s.selectedTime='';s.screen=item.id==='app-serveflow'?'service-detail':s.screen});return}
   if(target.dataset.day!==undefined){mutate(s=>s.selectedDay=Number(target.dataset.day));return}
   if(target.dataset.time){mutate(s=>s.selectedTime=target.dataset.time);return}
   if(target.dataset.filter!==undefined){mutate(s=>{s.filter=target.dataset.filter;s.query=''});return}
   if(target.dataset.add){mutate(s=>{const line=s.cart.find(x=>x.id===target.dataset.add);if(line)line.qty++;else s.cart.push({id:target.dataset.add,qty:1})});helpers.notice(helpers.tx('أُضيف إلى السلة التجريبية.','Added to the demo basket.'));return}
   if(target.dataset.qty){mutate(s=>{const line=s.cart.find(x=>x.id===target.dataset.qty);if(line)line.qty=Math.max(1,line.qty+Number(target.dataset.delta))});return}
   if(target.dataset.remove){mutate(s=>s.cart=s.cart.filter(x=>x.id!==target.dataset.remove));return}
   if(target.dataset.lesson){mutate(s=>{s.selected=target.dataset.lesson;s.screen='lesson';s.quiz=''});return}
   if(target.dataset.answer){mutate(s=>s.quiz=target.dataset.answer);return}
   if(target.dataset.membership){mutate(s=>s.membership=target.dataset.membership);helpers.notice(helpers.tx('تم تحديد الخيار في التجربة فقط.','Plan selected in this demo only.'));return}
   if(target.dataset.join){mutate(s=>{const id=target.dataset.join;if(s.joinedClasses.includes(id))s.joinedClasses=s.joinedClasses.filter(x=>x!==id);else s.joinedClasses.push(id)});helpers.notice(helpers.tx('تم تحديث الحصة المحجوزة تجريبياً.','Demo class selection updated.'));return}
   if(target.dataset.stock){mutate(s=>s.stockAdjustments[target.dataset.stock]=(Number(s.stockAdjustments[target.dataset.stock])||0)+Number(target.dataset.delta));return}
   if(target.dataset.student){mutate(s=>{s.selected=target.dataset.student;s.screen='student-detail'});return}
   if(target.dataset.attendance){mutate(s=>s.attendance[target.dataset.attendance]=!s.attendance[target.dataset.attendance]);return}
   if(target.dataset.action==='book'){const current=load(item.id);if(!current.selected||!current.selectedTime){helpers.notice(helpers.tx('اختر الخدمة والوقت أولاً.','Choose a service and time first.'),true);return}mutate(s=>{const svc=c.services.find(x=>x[0]===s.selected);s.appointments.unshift({serviceAr:svc[1],serviceEn:svc[2],day:s.selectedDay,time:s.selectedTime});s.screen='bookings'});helpers.notice(helpers.tx('تم تأكيد الموعد في المعاينة فقط.','Appointment confirmed in the demo only.'));return}
   if(target.dataset.action==='checkout'){mutate(s=>{if(!s.cart.length)return;const products=c.products;const fee=item.id==='app-saffron-run'?8:10;const total=s.cart.reduce((sum,x)=>sum+(products.find(p=>p[0]===x.id)?.[3]||0)*x.qty,0)+fee;s.orders.unshift({id:`DEMO-${Date.now().toString().slice(-6)}`,count:s.cart.reduce((n,x)=>n+x.qty,0),total,at:new Date().toISOString()});s.cart=[];s.screen='orders'});helpers.notice(helpers.tx('تم إنشاء طلب محلي تجريبي؛ لم يتم الدفع أو الإرسال.','Local demo order created; nothing was paid or sent.'));return}
   if(target.dataset.action==='new-expense'){mutate(s=>{s.expenseFormOpen=true;s.screen='transactions'});return}
   if(target.dataset.action==='cancel-expense'){mutate(s=>s.expenseFormOpen=false);return}
   if(target.dataset.action==='complete-lesson'){mutate(s=>{if(!s.doneLessons.includes(s.selected))s.doneLessons.push(s.selected);s.screen='progress'});helpers.notice(helpers.tx('تم حفظ تقدمك محلياً.','Progress saved locally.'));return}
   if(target.dataset.action==='sale'){const current=load(item.id),id=root.querySelector('[data-field="saleProduct"]')?.value||c.products[0][0],p=c.products.find(x=>x[0]===id),qty=p?Math.max(0,p[4]+(Number(current.stockAdjustments[id])||0)):0;if(!p||!qty){helpers.notice(helpers.tx('المخزون غير كافٍ لهذا الصنف.','Not enough stock for this item.'),true);return}mutate(s=>{s.stockAdjustments[id]=(Number(s.stockAdjustments[id])||0)-1;s.sales.unshift({id:`SALE-${Date.now().toString().slice(-6)}`,product:helpers.tx(p[1],p[2]),total:Number(p[3]),at:new Date().toISOString()});s.screen='sales'});helpers.notice(helpers.tx('سُجل بيع تجريبي وتم تحديث المخزون.','Demo sale recorded and stock updated.'));return}
   if(target.dataset.action==='continue-booking'){mutate(s=>{s.selectedTime='';s.screen='booking'});return}
   if(target.dataset.action==='confirm-service'){const current=load(item.id);if(!current.selectedTime){helpers.notice(helpers.tx('اختر وقتاً أولاً.','Choose a time first.'),true);return}mutate(s=>{const svc=c.services.find(x=>x[0]===s.selected)||c.services[0];s.requests.unshift({id:`HF-${Date.now().toString().slice(-6)}`,serviceAr:svc[1],serviceEn:svc[2],date:root.querySelector('[data-field="date"]')?.value||helpers.tx('الخميس ٥ نوفمبر','Thursday, Nov 5'),time:s.selectedTime});s.screen='requests'});helpers.notice(helpers.tx('أُنشئ طلب خدمة توضيحي داخل هذا التبويب.','Sample service request created in this tab.'));return}
 });
 root.addEventListener('input',event=>{const target=event.target.closest('[data-search]');if(!target)return;const state=load(item.id);state.query=target.value;save(item.id,state);const screen=root.querySelector('.zfx-app-demo');if(screen){const active=state.screen==='inventory'?'.za-inventory-table article':item.id==='app-campus-records'?'.za-student-row':'.za-product-card';screen.querySelectorAll(active).forEach(row=>{row.hidden=!row.textContent.toLocaleLowerCase().includes(target.value.toLocaleLowerCase())})}});
 root.addEventListener('change',event=>{const target=event.target.closest('[data-field]');if(!target)return;const state=load(item.id);state[target.dataset.field]=target.value;save(item.id,state)});
 root.addEventListener('submit',event=>{const form=event.target.closest('[data-form="expense"]');if(!form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));const amount=Number(data.amount);if(!data.label?.trim()||!Number.isFinite(amount)||amount<=0){helpers.notice(helpers.tx('أدخل وصفاً ومبلغاً صحيحين.','Enter a description and valid amount.'),true);return}const [categoryAr,categoryEn]=(data.category||'أخرى|Other').split('|');mutate(s=>{s.expenses.unshift({label:data.label.trim(),amount,categoryAr,categoryEn,category:categoryAr,at:new Date().toISOString()});s.expenseFormOpen=false});helpers.notice(helpers.tx('أُضيف المصروف إلى سجل هذه الجلسة فقط.','Expense added to this session only.'))});
}
